CREATE TRIGGER
  Emp_Before_Upd_Loan
  Before Update
  On Emp_Loan
  For Each Row
BEGIN
  If OLD.Loan_TAmt<>NEW.Loan_TAmt Then
    SET NEW.Loan_BAmt = NEW.Loan_BAmt + (NEW.Loan_TAmt-OLD.Loan_TAmt);
  End If;
  If OLD.Loan_MAmt<>NEW.Loan_MAmt Then
    SET NEW.Loan_EDate = ADD_MONTHS(NOW(),NEW.Loan_BAmt/NEW.Loan_MAmt);
  End If;
END$$
DELIMITER ;

