CREATE TRIGGER
  Emp_Before_Ins_TCGrad
  Before Insert
  On Emp_TCGrad
  For Each Row
BEGIN
  DECLARE nODegree   DECIMAL(38,10);
  SELECT TGrad_Id INTO nODegree FROM Emp_Emp WHERE Emp_Id=NEW.Emp_Id;
  SET NEW.TGrad_OId = nODegree;
  UPDATE Emp_Emp Set
         TGrad_Id     = NEW.TGrad_NId  ,
         Emp_GradDays = NEW.TGrad_Days ,
         Emp_GradSDate= NEW.TGrad_SDate,
         Emp_GradCons = 0,
         Emp_GradPuns = 0
   WHERE Emp_Id=NEW.Emp_Id;
Exception
  When Others Then
    NULL;
END$$
DELIMITER ;

